import{_ as t,o as a,c as o,a8 as r}from"./chunks/framework.BppdKxCY.js";const p=JSON.parse('{"title":"EP.21 打字机渲染","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.21-typewriter-render.md","filePath":"comics/EP.21-typewriter-render.md","lastUpdated":1792817913000}'),i={name:"comics/EP.21-typewriter-render.md"};function l(n,e,d,s,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ep-21-打字机渲染" tabindex="-1">EP.21 打字机渲染 <a class="header-anchor" href="#ep-21-打字机渲染" aria-label="Permalink to &quot;EP.21 打字机渲染&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../21-frontend-ai-interview">21-frontend-ai-interview.md</a>（21.2 打字机效果：从「能用」到「流畅」）· 示例：<code>examples/14-02-stream-chat.tsx</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君用 <code>setInterval</code> 每来一个 token 就 setState 一次，答案还没出完，页面已经卡成幻灯片，光标疯狂乱跳。</li><li><strong>第 2 格</strong>：码叔揭秘节奏算法——token 先入待渲染队列，<a href="https://developer.mozilla.org/zh-CN/docs/Web/API/Window/requestAnimationFrame" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>requestAnimationFrame</code></a> 每帧合批消费；积压多就加速、流结束快追平。</li><li><strong>第 3 格</strong>：像素酱实证三种方案：CSS <code>steps()</code> 适合固定横幅、setInterval 只配 Demo、rAF 队列才是流式 UI 的正解；切字还要按字形簇别切碎 emoji。</li><li><strong>第 4 格</strong>：码叔结案——别每帧全量解析 Markdown、自动滚动先贴底检测、停止就立即呈现全文。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-为什么逐字-setstate-会卡" tabindex="-1">第 1 格 · 为什么逐字 setState 会卡 <a class="header-anchor" href="#第-1-格-·-为什么逐字-setstate-会卡" aria-label="Permalink to &quot;第 1 格 · 为什么逐字 setState 会卡&quot;">​</a></h3><ul><li>token 到达频率可达 50~150 次/秒，每次 setState 都触发完整渲染管线；</li><li>若气泡里再做 Markdown 解析与高亮，CPU 被长任务占满 → 掉帧、输入框卡顿；</li><li>同步读 <code>scrollHeight</code> 再写滚动位置还会触发强制同步布局。</li></ul><h3 id="第-2-格-·-队列-raf-合批" tabindex="-1">第 2 格 · 队列 + rAF 合批 <a class="header-anchor" href="#第-2-格-·-队列-raf-合批" aria-label="Permalink to &quot;第 2 格 · 队列 + rAF 合批&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>网络 token ──▶ 待消费队列 ──▶ rAF 回调：本帧取 N 字 ──▶ 一次 setState</span></span></code></pre></div><ul><li>一帧内到达的多个 token <strong>合并成一次文本提交</strong>；</li><li>自适应速度：<code>步长 = clamp(积压 / 追平时长, 1, 单帧上限)</code>，既跟得上流又有打字感；</li><li>rAF 与刷新率对齐、切后台自动暂停；停止时取消 rAF 并一次性显示已到达全文。</li></ul><h3 id="第-3-格-·-三方案与字符粒度" tabindex="-1">第 3 格 · 三方案与字符粒度 <a class="header-anchor" href="#第-3-格-·-三方案与字符粒度" aria-label="Permalink to &quot;第 3 格 · 三方案与字符粒度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>评价</th></tr></thead><tbody><tr><td>CSS <code>steps()</code> + width</td><td>零 JS，但中文变宽字符崩版、不能接动态流</td></tr><tr><td>setInterval 逐字</td><td>直观但后台漂移、与刷新不同步</td></tr><tr><td><strong>rAF 队列消费</strong></td><td>合批、可暂停/继续/中止，生产首选</td></tr></tbody></table><ul><li><code>str[i]</code> 按 UTF-16 码元切，会切碎 emoji 代理对；<code>for...of</code> 按码点，组合字形用 <code>Intl.Segmenter(granularity:&#39;grapheme&#39;)</code>。</li></ul><h3 id="第-4-格-·-高级体验细节" tabindex="-1">第 4 格 · 高级体验细节 <a class="header-anchor" href="#第-4-格-·-高级体验细节" aria-label="Permalink to &quot;第 4 格 · 高级体验细节&quot;">​</a></h3><ul><li>光标用 <code>::after</code> + opacity 闪烁，只动合成层属性，并尊重 <code>prefers-reduced-motion</code>；</li><li>Markdown 解析降频到 50~100ms 一次，流结束做终态渲染（详见 EP.24）；</li><li>贴底检测：距底 &lt; 80px 才自动跟随，否则显示&quot;新内容 ↓&quot;按钮，不抢用户阅读位置。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../21-frontend-ai-interview#_21-7-3-常见误区总清单">《21.7.3 常见误区总清单》</a></p></blockquote><ol><li>每 token 一次渲染：长任务 + 掉帧，必须 rAF 合批；</li><li>无脑 <code>scrollTop = scrollHeight</code>：用户上滑被强行拽回底部；</li><li><code>str[i]</code> 切字：emoji 乱码，用码点/字形簇；</li><li>停止后还在慢慢吐字：用户点停止应立即呈现全部已到达文本并清空队列。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li><strong>为什么 rAF 比 setInterval 更适合打字机？</strong>——与屏幕刷新对齐不掉帧；后台标签页自动暂停不堆积爆发；一帧只提交一次，天然合批。</li><li><strong>网络突然吐来一大段时怎么办？</strong>——按帧预算自适应加速（积压/追平时长，夹上单帧上限）；流结束允许快速追平，并提供&quot;立即显示全部&quot;，消费体验优先于打字形式。</li><li><strong>打字机有哪些重排陷阱？</strong>——避免逐字改 width/height、避免读后立刻写造成强制同步布局；容器定宽、滚动在下一帧统一处理、光标只动 opacity。</li></ol>',20)])])}const m=t(i,[["render",l]]);export{p as __pageData,m as default};
